// === Tab: Particle ===
class Particle{
	constructor(pos, heading, h){
		this.pos = pos;
		this.heading = heading;
		this.stop = false;
		this.t = random(1000)
		this.h = h;
	}

	display(){
		colorMode(HSB);
		stroke(this.h,150,255,0.1)
		strokeWeight(2)
		point(this.pos.x,this.pos.y)
	}

	update(){
		this.pos = this.pos.add(createVector(cos(this.heading),sin(this.heading)))
		this.heading += (noise(this.t)-0.5)*0.05
		this.t+=0.01
	}
}

// === Tab: Circle ===
class Circle{
	constructor(pos, r){
		this.pos = pos;
		this.r = r;
	}
}

